def signal(obs):
    # low-turnover momentum: follow 100-step drift, hold until opposite signal
    # thresholds approx 0.5 sigma of 100-step return: vol*sqrt(L)
    thresh = {'A': 5.0, 'B': 2.5, 'C': 3.5, 'IDX': 6.0}
    out = {}
    # obs.assets is available; fallback to list
    try:
        assets = obs.assets
    except:
        assets = ['A','B','C','IDX']
    for a in assets:
        try:
            m = obs.hist(a, 'mid', 110)
            if m is None:
                continue
            # need at least 101 points for 100-step lookback (m is array of last n mids)
            if len(m) < 101:
                continue
            last = m[-1]
            prev100 = m[-101]
            if np.isnan(last) or np.isnan(prev100):
                continue
            past100 = last - prev100
            th = thresh.get(a, 5.0)
            if past100 > th:
                out[a] = 1.0
            elif past100 < -th:
                out[a] = -1.0
            else:
                # no change -> keep previous target (do not include)
                # but to avoid holding stale forever, we keep; turnover stays low
                pass
        except:
            continue
    return out

