def signal(obs):
    n = 400
    try:
        mA = obs.hist('A','mid',n)
        mB = obs.hist('B','mid',n)
        mC = obs.hist('C','mid',n)
        mI = obs.hist('IDX','mid',n)
    except Exception:
        return {}
    wA=0.3333; wB=0.6667; wC=0.1667
    syn = wA*mA + wB*mB + wC*mC
    basis = mI - syn
    b = basis[-1]
    if b != b:  # NaN
        return {}
    # rolling mean/std
    import numpy as _np  # will fail? no imports allowed - use np
    m = np.nanmean(basis)
    s = np.nanstd(basis)
    if not (s==s) or s < 1e-6:
        return {}
    z = (b - m)/s
    # trade IDX only, contrarian, with deadzone
    # scale: z=1 -> 0.5 position
    t = -z * 0.5
    # deadzone for small |z|
    if abs(z) < 0.5:
        t = 0.0
    t = max(-1.0, min(1.0, t))
    return {'IDX': float(t)}

