import math
# momentum analysis across assets and lags
def mom_ic(asset, L, H):
    m = H[asset]['mid']
    # forward 50 step return
    n=len(m)
    # compute past momentum and forward return
    past = np.empty(n)
    past[:] = np.nan
    fwd = np.empty(n)
    fwd[:]=np.nan
    for i in range(L, n-50):
        if not np.isnan(m[i]) and not np.isnan(m[i-L]):
            past[i]=m[i]-m[i-L]
        if not np.isnan(m[i+50]) and not np.isnan(m[i]):
            fwd[i]=m[i+50]-m[i]
    valid = ~np.isnan(past) & ~np.isnan(fwd)
    if np.sum(valid)<100:
        return np.nan, np.nan
    # correlation
    corr = np.corrcoef(past[valid], fwd[valid])[0,1]
    # spearman approximate via rank? use pearson
    # hit rate of sign
    hit = np.mean(np.sign(past[valid])==np.sign(fwd[valid]))
    return corr, hit

