            mom=mid[t]-mid[t-L]
            if not np.isnan(mom):
                if mom>thresh:
                    target= -1 if fade else 1
                elif mom< -thresh:
                    target= 1 if fade else -1
                # else hold
        desired=int(round(target*10))
        if cur<desired:
            cur+=1
            if not np.isnan(spread[t]): pnl[t]-= spread[t]/2
        elif cur>desired:
            cur-=1
            if not np.isnan(spread[t]): pnl[t]-= spread[t]/2
        if not np.isnan(mid[t]) and not np.isnan(mid[t-1]):
            pnl[t]+= cur*(mid[t]-mid[t-1])
    return pnl

