def signal(obs):
    # robust dual-timeframe momentum with imbalance confirmation
    # thresholds calibrated: vol*sqrt(L)*0.65 approx 8-9 for A/C L100, ~6 for L50
    th100 = {'A': 9.0, 'C': 9.0, 'IDX': 7.0}
    th50  = {'A': 6.0, 'C': 6.0, 'IDX': 5.0}
    out = {}
    try:
        if obs.position.get('B', 0) != 0:
            out['B'] = 0.0
    except:
        pass
    for a in ('A','C','IDX'):
        try:
            m = obs.hist(a, 'mid', 210)
            if m is None or len(m) < 101:
                continue
            if np.isnan(m[-1]):
                continue
            # need 100 and 50 lookbacks
            if len(m) < 101:
                continue
            mom100 = m[-1] - m[-101]
            # m[-51] corresponds to 50 steps ago (inclusive)
            mom50 = m[-1] - m[-51]
            if np.isnan(mom100) or np.isnan(mom50):
                continue
            # imbalance confirmation - recent 10 avg
            ok_long = True
            ok_short = True
            try:
                imb = obs.hist(a, 'imbalance', 20)
                if imb is not None and len(imb) >= 10:
                    v = imb[~np.isnan(imb)]
                    if len(v) >= 5:
                        k = 10 if len(v) >= 10 else len(v)
                        avg_imb = np.mean(v[-k:])
                        # require not strongly opposite; stronger filter than before
                        if avg_imb < -0.10:
                            ok_long = False
                        if avg_imb > 0.10:
                            ok_short = False
                        # optional: if momentum strong, need imbalance same side for extra confidence when choppy
                        # but keep permissive to not miss trends
            except:
                pass

            # dual timeframe agreement
            if mom100 > th100[a] and mom50 > th50[a] and ok_long:
                out[a] = 1.0
            elif mom100 < -th100[a] and mom50 < -th50[a] and ok_short:
                out[a] = -1.0
            elif mom100 * mom50 < 0:
                # disagreement = chop -> flatten to avoid whipsaw
                # only flatten if we currently have position, else stay flat
                # use state to know if we were positioned? just send 0 to reduce exposure
                # check current position target via obs.position: if flat already don't send
                prev = obs.position.get(a, 0)
                if prev != 0:
                    # if momentum magnitude small, also flatten
                    out[a] = 0.0
                # else leave missing = keep 0
            # else keep previous target (missing asset = hold)
        except:
            continue
    return out

