def mom_ic(asset, lag, horizon=50):
    mid = H[asset]['mid']
    n = len(mid)
    sig=[]
    fut=[]
    for i in range(lag, n-horizon):
        if np.isnan(mid[i]) or np.isnan(mid[i-lag]) or np.isnan(mid[i+horizon]):
            continue
        past = mid[i] - mid[i-lag]
        fwd = mid[i+horizon] - mid[i]
        sig.append(past)
        fut.append(fwd)
    if len(sig) < 100:
        return (None, 0)
    sig=np.array(sig); fut=np.array(fut)
    ic=np.corrcoef(sig,fut)[0,1]
    return (float(ic), len(sig))

def premium_stats():
    mA=H['A']['mid']; mB=H['B']['mid']; mC=H['C']['mid']; mI=H['IDX']['mid']
    n=len(mA)
    basket=0.3333*mA + 0.6667*mB + 0.1667*mC
    prem=mI-basket
    valid= ~np.isnan(prem) & ~np.isnan(mA) & ~np.isnan(mB) & ~np.isnan(mC) & ~np.isnan(mI)
    p=prem[valid]
    mean=float(np.nanmean(p))
    std=float(np.nanstd(p))
    def autocorr(x, lag):
        xm=np.nanmean(x)
        x2=x-xm
        return float(np.corrcoef(x2[:-lag], x2[lag:])[0,1]) if len(x)>lag+10 else None
    ac1=autocorr(p,1)
    ac10=autocorr(p,10)
    results={}
    for h in [10,50,100]:
        sig=[]; fut_prem=[]; fut_idx=[]
        for i in range(n-h-1):
            if np.isnan(prem[i]) or np.isnan(mI[i+h]) or np.isnan(mI[i]):
                continue
            sig.append(prem[i])
            fut_prem.append(prem[i+h]-prem[i])
            fut_idx.append(mI[i+h]-mI[i])
        sig=np.array(sig); fut_prem=np.array(fut_prem); fut_idx=np.array(fut_idx)
        results[h]={
            'corr_prem_vs_future_premium_change': float(np.corrcoef(sig,fut_prem)[0,1]),
            'corr_prem_vs_future_IDX_move': float(np.corrcoef(sig,fut_idx)[0,1])
        }
    mean_abs=float(np.nanmean(np.abs(p)))
    return (mean,std,ac1,ac10,results,mean_abs)

