def window_pnl( asset, lag, th, start, end, horizon=50):
    mid=H[asset]['mid']; spread=H[asset]['spread']
    pnl=0; pos=0; trades=0
    for t in range(start+lag, end, 10):
        if t>= len(mid)-horizon: break
        if np.isnan(mid[t]) or np.isnan(mid[t-lag]): continue
        past=mid[t]-mid[t-lag]
        target=0
        if past>th: target=1
        elif past< -th: target=-1
        else: continue # hold
        fut=mid[t+horizon]-mid[t]
        if np.isnan(fut): continue
        s=spread[t] if not np.isnan(spread[t]) else 8
        cost=abs(target-pos)*s/2 if target!=pos else 0
        pnl+= target*fut - cost
        if target!=pos: trades+=1
        pos=target
    return pnl

